  "story-problems.join.startsWithSomeAnd": "{Nc} empieza con algun{it.o}s {it} y luego consigue más, así que la cantidad <strong>crece</strong>. Un inicio y una cantidad que se agrega, juntos → <strong>suma</strong>.",
  "story-problems.join.weKnowTheStart": "Sabemos el inicio ({a}) y el final ({c}). Lo que falta es el cambio de en medio: inicio + ? = final. Para encontrar una parte que falta, quita del total la parte que conocemos → <strong>resta</strong>: final − inicio.",
  "story-problems.join.weKnowWhatWas": "Sabemos lo que se agregó ({b}) y el final ({c}), pero no el inicio: ? + {b2} = {c2}. El inicio es una parte que falta del final → <strong>resta</strong>: final − agregado.",
