  "story-problems.join.startEnd": "inicio + {QM} = final",
  "story-problems.join.addedEnd": "{QM} + agregado = final",
  "story-problems.join.keyWordsAreClues": "Las palabras clave son pistas, no reglas. Aquí “más” sí quiere decir sumar, porque {N} termina con más. Pero en “Ana tiene 12 conchas, 5 más que Ben”, la palabra “más” va con restar: Ben tiene 12 − 5.",
  "story-problems.join.theStorySaysMore": "El problema dice “más”, pero sumar {a} + {c} = {add} daría más de lo que {N} tiene al final: eso no puede ser lo que se agregó. Las palabras clave pueden engañar; el dibujo no.",
  "story-problems.join.gotMoreButWere": "{N} consiguió más, pero buscamos el inicio, que es menor que el final: por eso este problema de “más” se resuelve restando.",
