  "story-problems.work.theSameSevenSteps": "Los mismos siete pasos sirven para todos los problemas verbales: léelo, di qué te preguntan, anota lo que sabes, elige la operación y di por qué, dibújalo, resuélvelo, y luego contesta con una oración y comprueba.",
