  "story-problems.read.itMultipliesTheChoices": "Multiplica las opciones, ordena las cosas cuando el orden importa (nPr), elige grupos cuando no importa (nCr) y cuenta apretones de manos, partidos y diagonales, con un árbol o un dibujo en cada paso.",
