  "story-problems.read.aSequenceProblem": "un problema de sucesiones",
  "story-problems.read.theRateMachine": "The Rate Machine",
  "story-problems.read.aRelatedRatesProblem": "un problema de razones de cambio relacionadas (qué tan rápido cambia una cosa mientras cambia otra)",
  "story-problems.read.itsRelatedRatesTab": "Su pestaña de razones relacionadas lo dibuja, escribe la ecuación, la deriva con respecto al tiempo y solo después pone los números de ese momento.",
  "story-problems.read.theGraphPaper": "The Graph Paper",
  "story-problems.read.aProblemWithSeveral": "un problema con varios límites a la vez (programación lineal)",
  "story-problems.read.itsOptimizationTabWrites": "Su pestaña de optimización escribe una desigualdad por cada límite, sombrea la región donde se cumplen todas y prueba sus esquinas para encontrar la mejor.",
  "story-problems.read.anOptimizationProblemThe": "un problema de optimización (el valor más grande o más pequeño posible)",
  "story-problems.read.itsOptimizationTabWrites2": "Su pestaña de optimización escribe la función, encuentra su dominio, deriva, resuelve f′ = 0 y comprueba que sea la mejor.",
  "story-problems.read.aBestPriceProblem": "un problema del mejor precio (el mayor ingreso)",
  "story-problems.read.itsOptimizationTabWrites3": "Su pestaña de optimización escribe ingreso = precio × cantidad vendida como función del cambio de precio y encuentra dónde su derivada es 0.",
  "story-problems.read.aProblemWithSeveral2": "un problema con varias desigualdades a la vez (programación lineal)",
  "story-problems.read.writeOneInequalityFor": "Escribe una desigualdad por cada límite, sombréalas en la pestaña de desigualdades y prueba las esquinas de la región sombreada.",
  "story-problems.read.theAreaBox": "The Area Box",
  "story-problems.read.writingAnExpression": "escribir una expresión",
  "story-problems.read.multiplyTheLengthWidth": "Multiplica el largo, el ancho y la altura que quedan después de cortar; luego The Area Box puede desarrollar el producto.",
  "story-problems.read.theMatrixGrid": "The Matrix Grid",
  "story-problems.read.aSystemOfThree": "un sistema de tres ecuaciones",
  "story-problems.read.writeOneEquationFor": "Escribe una ecuación por cada total disponible (una incógnita por cada tipo) y luego resuelve las tres juntas.",
  "story-problems.read.aProblemThatCant": "un problema que no puede ser cierto tal como está escrito",
  "story-problems.read.anEquilateralTrianglesHeight": "La altura de un triángulo equilátero siempre es más o menos 0.866 veces su lado, así que su base y su altura no pueden estar en la razón que se da. Revisa el problema (¿es un triángulo isósceles o rectángulo?).",
  "story-problems.read.aProblemThatNeeds": "un problema que necesita un número que no da",
  "story-problems.read.theDistanceAlongThe": "La distancia a lo largo de la órbita necesita el radio de la órbita: el radio de la Tierra (unos 6,371 km) más la altura. Y “qué tan lejos” puede ser a lo largo de la órbita o en línea recta. Agrega eso, y The Shape Shop puede encontrar la circunferencia.",
  "story-problems.read.aWhatFractionQuestion": "una pregunta de “qué fracción”",
  "story-problems.read.itsAnswerIsA": "Su respuesta es una fracción: la parte por la que pregunta sobre el total (las rebanadas que quedan sobre todas las rebanadas). Esta página todavía no resuelve esos; The Fraction Bar puede simplificar la fracción cuando la tengas.",
  "story-problems.read.addingUpCoins": "sumar monedas",
  "story-problems.read.addWhatTheCoins": "Suma lo que valen las monedas (un quarter vale 25¢, un dime 10¢, un nickel 5¢, un penny 1¢). La pestaña Money de The Place Value Chart lo hace moneda por moneda: escribe ahí solo las monedas, como “3 quarters 4 dimes”.",
  "story-problems.read.theStoryDoesntNeed": "el problema no lo necesita para esta pregunta",
