  "story-problems.draw.iCanSeeBut": "Veo {x}, pero la pregunta no pide una cantidad, así que no sé bien qué calcular. Los problemas verbales preguntan cosas como “¿Cuántos …?”, “¿Cuánto …?”, “¿A qué hora …?” o “¿Cuál es el total …?”. Cambia la pregunta o, si de verdad es un problema verbal, elige el tipo abajo.",
  "story-problems.draw.theNumbers": "los números {andList}",
  "story-problems.draw.aQuestion": "una pregunta",
  "story-problems.draw.iCanSeeThe": "Veo los números {andList}, pero no la pregunta: la oración que dice qué hay que encontrar (casi siempre termina con <b>?</b>, como “¿Cuántos … hay en total?”). Agrégala al problema o elige abajo el tipo de problema.",
  "story-problems.draw.iCouldntFindAny": "No encontré ningún número en ese problema, así que todavía no hay nada que calcular. Revisa el problema, o elige abajo el tipo de problema y escribe los números en <b>Lo que dice el problema</b>.",
  "story-problems.draw.iFoundButI": "Encontré {x}, pero no supe qué tipo de problema es. No pasa nada: los problemas se pueden escribir de muchas formas. ¿De qué tipo es? Elige uno abajo y yo pongo los números en orden; luego corrige lo que haga falta en <b>Lo que dice el problema</b>.",
  "story-problems.draw.noNumbersICould": "ningún número que pudiera usar",
  "story-problems.draw.somethingInThereDivides": "Algo ahí divide entre cero, y eso no se puede. Cambia el 0.",
  "story-problems.draw.somethingWentWrongWorking": "Algo salió mal al resolver ese: prueba con otros números.",
  "story-problems.draw.of": "{step} de {total}",
  "story-problems.reader.none": "none|{src}",
  "story-problems.reader.whatTheStorySays": "Lo que dice el problema <span>— todavía no he leído nada</span>",
  "story-problems.reader.whatIReadFix": "Lo que leí: {TLABEL}{x} <span>· {numsLine} · corrige lo que haga falta aquí</span>",
  "story-problems.reader.whatTheStorySays2": "Lo que dice el problema <span>— cambia un número o lo que falta</span>",
  "story-problems.reader.kindOfStoryPick": "<p class=\"rd-say\">{x}</p><div class=\"rd-grid\"><div class=\"rd-f\"><label for=\"rdType\">Tipo de problema</label><select id=\"rdType\"><option value=\"\">— elige uno —</option>{map}</select></div></div>",
  "story-problems.reader.pickTheKindOf": "Elige el tipo de problema, y los números van en los cuadros en el orden en que aparecen.",
  "story-problems.reader.heresHowIRead": "Así lo leí. Si algo quedó mal —el tipo de problema, qué número es cuál o qué falta—, cámbialo aquí y el procedimiento se actualiza.",
  "story-problems.reader.thisStoryIsWritten": "Este problema está escrito a partir de estos números. Cambia cualquiera de ellos, o lo que falta, y el problema se vuelve a escribir.",
  "story-problems.reader.kindOfStory": "<div class=\"rd-grid\"><div class=\"rd-f\"><label for=\"rdType\">Tipo de problema</label><select id=\"rdType\">{map}</select></div>",
  "story-problems.reader.whichKind": "<div class=\"rd-f\"><label for=\"rdKind\">Qué tipo</label><select id=\"rdKind\">{map}</select></div>",
  "story-problems.reader.whichForm": "<div class=\"rd-f\"><label for=\"rdForm\">Qué forma</label><select id=\"rdForm\">{forms}</select></div>",
  "story-problems.reader.whatsAsked": "<div class=\"rd-f\"><label for=\"rdAsk\">Qué se pregunta</label><select id=\"rdAsk\">{x}</select></div>",
